body.html:
{% comment -%}
JTL-Software Template für E-Mail "Rechnung (HTML-Format)", Stand: 201810101
--------------------------------------------------------------------------------------------------------------
Sie können das Template über folgende Variablen steuern:
--------------------------------------------------------------------------------------------------------------
{% endcomment -%}
{% assign FirmenLogoUrl = '' %}{% comment %}Link zum Firmenlogo (600px breit), z.B: http://www.jtl-software.de/bilder/intern/shoplogo/jtlshoplogo.png{% endcomment -%}
{% assign TwitterProfileUrl= '' %}{% comment %}Link zum Twitter-Profil, z.B: https://twitter.com/JTLSoftware{% endcomment -%}
{% assign FacebookProfileUrl= '' %}{% comment %}Link zum Facebook-Profil, z.B: https://www.facebook.com/JTLSoftware{% endcomment -%}
{% assign GoogleProfileUrl= '' %}{% comment %}Link zum Google+-Profil, z.B: https://plus.google.com/109750496801379835262{% endcomment -%}
{% assign IncludeArtikelnummern = false %}{% comment %}Gibt an, ob die Artikelnummern ausgegeben werden{% endcomment -%}
{% assign IncludeEinzelpreise = false %}{% comment %}Gibt an, ob die Einzelpreise ausgegeben werden{% endcomment -%}

{% comment -%}
--------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------
Unterhalb dieses Bereiches sollten nur erfahrene Anwender Änderungen vornehmen. Bei Fragen
steht Ihnen unser Supportforum unter http://forum.jtl-software.de/formulardesigner-editor-open-beta-phase/
zur Verfügung. Gerne helfen Ihnen auch unsere Servicepartner weiter. Einen qualifizierten Service-Partner
finden Sie unter http://www.jtl-software.de/Servicepartner.
Die mit @editable gekennzeichneten CSS-Eigenschaften sind für das Layout zuständig. Die anderen CSS-Eigenschaften
dienen teilweise zur Kompatibilität und sollten nur mit großer Vorsicht verändert werden.
--------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------
{% endcomment -%}
{% assign NettoPreiseBenutzen = false -%}
{% if Specification.UseNetPrices == true -%}
{% assign NettoPreiseBenutzen = true -%}
{% endif -%}
<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.0 Transitional//EN" "http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd">
<html xmlns="http://www.w3.org/1999/xhtml">
    <head>
        <!-- Lizenz für dieses Mailtemplate: CC BY-SA 3.0 -->
        <!-- Quelle: https://github.com/mailchimp/Email-Blueprints, angepasst für JTL-Wawi -->
        <meta http-equiv="Content-Type" content="text/html; charset=UTF-8" />
        <title>Ihre Rechnung über "{{ Report.InvoicePosition[0].Name | Truncate: 20 }}"{% case Report.InvoicePosition.Size %}{% when 0%}{% when 1 %}{% when 2 %} und einem weiteren Artikeln{% else %} und {{ Report.InvoicePosition.Size | Minus: 1 }} weiteren Artikeln{% endcase%} bei {{ Report.Company.CompanyName }}</title>
        <style type="text/css">      
            /* /\/\/\/\/\/\/\/\/ CLIENT-SPECIFIC STYLES /\/\/\/\/\/\/\/\/ */
            #outlook a{padding:0;} /* Force Outlook to provide a "view in browser" message */
            .ReadMsgBody{width:100%;} .ExternalClass{width:100%;} /* Force Hotmail to display emails at full width */
            .ExternalClass, .ExternalClass p, .ExternalClass span, .ExternalClass font, .ExternalClass td, .ExternalClass div {line-height: 100%;} /* Force Hotmail to display normal line spacing */
            body, table, td, p, a, li, blockquote{-webkit-text-size-adjust:100%; -ms-text-size-adjust:100%;} /* Prevent WebKit and Windows mobile changing default text sizes */
            table, td{mso-table-lspace:0pt; mso-table-rspace:0pt;} /* Remove spacing between tables in Outlook 2007 and up */
            img{-ms-interpolation-mode:bicubic;} /* Allow smoother rendering of resized image in Internet Explorer */

            /* /\/\/\/\/\/\/\/\/ RESET STYLES /\/\/\/\/\/\/\/\/ */
            body{margin:0; padding:0;}
            img{border:0; height:auto; line-height:100%; outline:none; text-decoration:none;}
            table{border-collapse:collapse !important;}
            body, #bodyTable, #bodyCell{height:100% !important; margin:0; padding:0; width:100% !important;}

            /* /\/\/\/\/\/\/\/\/ TEMPLATE STYLES /\/\/\/\/\/\/\/\/ */

            /* ========== Page Styles ========== */

            #bodyCell{padding:20px;}
            #templateContainer{width:800px;}

            /**
            * @tab Page
            * @section background style
            * @tip Set the background color and top border for your email. You may want to choose colors that match your company's branding.
            * @theme page
            */
            body, #bodyTable{
                /*@editable*/ background-color:#DEE0E2;
            }

            /**
            * @tab Page
            * @section background style
            * @tip Set the background color and top border for your email. You may want to choose colors that match your company's branding.
            * @theme page
            */
            #bodyCell{
                /*@editable*/ border-top:4px solid #BBBBBB;
            }

            /**
            * @tab Page
            * @section email border
            * @tip Set the border for your email.
            */
            #templateContainer{
                /*@editable*/ border:1px solid #BBBBBB;
            }

            /**
            * @tab Page
            * @section heading 1
            * @tip Set the styling for all first-level headings in your emails. These should be the largest of your headings.
            * @style heading 1
            */
            h1{
                /*@editable*/ color:#202020 !important;
                display:block;
                /*@editable*/ font-family:Helvetica;
                /*@editable*/ font-size:26px;
                /*@editable*/ font-style:normal;
                /*@editable*/ font-weight:bold;
                /*@editable*/ line-height:100%;
                /*@editable*/ letter-spacing:normal;
                margin-top:0;
                margin-right:0;
                margin-bottom:10px;
                margin-left:0;
                /*@editable*/ text-align:right;
            }

            /**
            * @tab Page
            * @section heading 2
            * @tip Set the styling for all second-level headings in your emails.
            * @style heading 2
            */
            h2{
                /*@editable*/ color:#404040 !important;
                display:block;
                /*@editable*/ font-family:Helvetica;
                /*@editable*/ font-size:20px;
                /*@editable*/ font-style:normal;
                /*@editable*/ font-weight:bold;
                /*@editable*/ line-height:100%;
                /*@editable*/ letter-spacing:normal;
                margin-top:0;
                margin-right:0;
                margin-bottom:10px;
                margin-left:0;
                /*@editable*/ text-align:left;
            }

            /**
            * @tab Page
            * @section heading 3
            * @tip Set the styling for all third-level headings in your emails.
            * @style heading 3
            */
            h3{
                /*@editable*/ color:#606060 !important;
                display:block;
                /*@editable*/ font-family:Helvetica;
                /*@editable*/ font-size:16px;
                /*@editable*/ font-style:italic;
                /*@editable*/ font-weight:normal;
                /*@editable*/ line-height:100%;
                /*@editable*/ letter-spacing:normal;
                margin-top:0;
                margin-right:0;
                margin-bottom:10px;
                margin-left:0;
                /*@editable*/ text-align:left;
            }

            /**
            * @tab Page
            * @section heading 4
            * @tip Set the styling for all fourth-level headings in your emails. These should be the smallest of your headings.
            * @style heading 4
            */
            h4{
                /*@editable*/ color:#808080 !important;
                display:block;
                /*@editable*/ font-family:Helvetica;
                /*@editable*/ font-size:14px;
                /*@editable*/ font-style:italic;
                /*@editable*/ font-weight:normal;
                /*@editable*/ line-height:100%;
                /*@editable*/ letter-spacing:normal;
                margin-top:0;
                margin-right:0;
                margin-bottom:10px;
                margin-left:0;
                /*@editable*/ text-align:left;
            }

            /* ========== Header Styles ========== */

            /**
            * @tab Header
            * @section preheader style
            * @tip Set the background color and bottom border for your email's preheader area.
            * @theme header
            */
            #templatePreheader{
                /*@editable*/ background-color:#F4F4F4;
                /*@editable*/ border-bottom:1px solid #CCCCCC;
            }

            /**
            * @tab Header
            * @section preheader text
            * @tip Set the styling for your email's preheader text. Choose a size and color that is easy to read.
            */
            .preheaderContent{
                /*@editable*/ color:#808080;
                /*@editable*/ font-family:Helvetica;
                /*@editable*/ font-size:10px;
                /*@editable*/ line-height:125%;
                /*@editable*/ text-align:left;
            }

            /**
            * @tab Header
            * @section preheader link
            * @tip Set the styling for your email's preheader links. Choose a color that helps them stand out from your text.
            */
            .preheaderContent a:link, .preheaderContent a:visited, /* Yahoo! Mail Override */ .preheaderContent a .yshortcuts /* Yahoo! Mail Override */{
                /*@editable*/ color:#606060;
                /*@editable*/ font-weight:normal;
                /*@editable*/ text-decoration:underline;
            }

            /**
            * @tab Header
            * @section header style
            * @tip Set the background color and borders for your email's header area.
            * @theme header
            */
            #templateHeader{
                /*@editable*/ background-color:#F4F4F4;
                /*@editable*/ border-top:1px solid #FFFFFF;
                /*@editable*/ border-bottom:1px solid #CCCCCC;
            }

            /**
            * @tab Header
            * @section header text
            * @tip Set the styling for your email's header text. Choose a size and color that is easy to read.
            */
            .headerContent{
                /*@editable*/ color:#505050;
                /*@editable*/ font-family:Helvetica;
                /*@editable*/ font-size:20px;
                /*@editable*/ font-weight:bold;
                /*@editable*/ line-height:100%;
                /*@editable*/ padding-top:20px;
                /*@editable*/ padding-right:20px;
                /*@editable*/ padding-bottom:20px;
                /*@editable*/ padding-left:20px;
                /*@editable*/ text-align:left;
                /*@editable*/ vertical-align:middle;
            }

            .headerLogo {

            }

            .headerSummary {
                /*@editable*/ text-align: right;
            }

            /**
            * @tab Header
            * @section header link
            * @tip Set the styling for your email's header links. Choose a color that helps them stand out from your text.
            */
            .headerContent a:link, .headerContent a:visited, /* Yahoo! Mail Override */ .headerContent a .yshortcuts /* Yahoo! Mail Override */{
                /*@editable*/ color:#EB4102;
                /*@editable*/ font-weight:normal;
                /*@editable*/ text-decoration:underline;
            }

            .PositionImage {
                width: 50px;
                height: 50px;
            }

            .PositionPrice, .SumPosPrice, .PaymentsPrice {
                /*@editable*/ vertical-align: top;
                /*@editable*/ text-align: right;
                /*@editable*/ width: 10em;
            }

            .SumPosDescription, .PaymentsDescription {
                /*@editable*/ text-align: right;
            }

            .PositionProperties {
                /*@editable*/ font-size: 80%;
                border-collapse: collapse !important;
                border-spacing: 50px 50px !important;
            }

            .PositionProperties .spacer div { 
                /*@editable*/ width: 1em;
            }            

            .PositionProperties .name { 
                /*@editable*/ font-style: italic;
                /*@editable*/ vertical-align: top;              
            }

            .PositionProperties .content { 
                /*@editable*/ width: 100%;
            }

            .PositionChildren {
                /*@editable*/ font-size: 80%;
            }

            .PositionChildren .spacer div { 
                /*@editable*/ width: 1em;
            }

            .PositionChildren .bullet { 
                /*@editable*/ vertical-align: top;
            }

            .PositionChildren .content { 
                /*@editable*/ width: 100%;
                margin-left: 1em;
            }

            .PositionImage img {
                padding: 5px;
            }

            #headerImage{
                height:auto;
                max-width:600px;
            }

            /* ========== Body Styles ========== */

            /**
            * @tab Body
            * @section body style
            * @tip Set the background color and borders for your email's body area.
            */
            #templateBody{
                /*@editable*/ background-color:#F4F4F4;
                /*@editable*/ border-top:1px solid #FFFFFF;
                /*@editable*/ border-bottom:1px solid #CCCCCC;
            }

            /**
            * @tab Body
            * @section body text
            * @tip Set the styling for your email's main content text. Choose a size and color that is easy to read.
            * @theme main
            */
            .bodyContent{
                /*@editable*/ color:#505050;
                /*@editable*/ font-family:Helvetica;
                /*@editable*/ font-size:14px;
                /*@editable*/ line-height:150%;
                padding-top:20px;
                padding-right:20px;
                padding-bottom:20px;
                padding-left:20px;
                /*@editable*/ text-align:left;
            }

            /**
            * @tab Body
            * @section body link
            * @tip Set the styling for your email's main content links. Choose a color that helps them stand out from your text.
            */
            .bodyContent a:link, .bodyContent a:visited, /* Yahoo! Mail Override */ .bodyContent a .yshortcuts /* Yahoo! Mail Override */{
                /*@editable*/ color:#EB4102;
                /*@editable*/ font-weight:normal;
                /*@editable*/ text-decoration:underline;
            }

            .bodyContent img{
                display:inline;
                height:auto;
                max-width:560px;
            }

            /* ========== Footer Styles ========== */

            /**
            * @tab Footer
            * @section footer style
            * @tip Set the background color and borders for your email's footer area.
            * @theme footer
            */
            #templateFooter{
                /*@editable*/ background-color:#F4F4F4;
                /*@editable*/ border-top:1px solid #FFFFFF;
            }

            /**
            * @tab Footer
            * @section footer text
            * @tip Set the styling for your email's footer text. Choose a size and color that is easy to read.
            * @theme footer
            */
            .footerContent{
                /*@editable*/ color:#808080;
                /*@editable*/ font-family:Helvetica;
                /*@editable*/ font-size:10px;
                /*@editable*/ line-height:150%;
                padding-top:20px;
                padding-right:20px;
                padding-bottom:20px;
                padding-left:20px;
                /*@editable*/ text-align:left;
            }

            /**
            * @tab Footer
            * @section footer link
            * @tip Set the styling for your email's footer links. Choose a color that helps them stand out from your text.
            */
            .footerContent a:link, .footerContent a:visited, /* Yahoo! Mail Override */ .footerContent a .yshortcuts, .footerContent a span /* Yahoo! Mail Override */{
                /*@editable*/ color:#606060;
                /*@editable*/ font-weight:normal;
                /*@editable*/ text-decoration:underline;
            }

            /* /\/\/\/\/\/\/\/\/ MOBILE STYLES /\/\/\/\/\/\/\/\/ */

            @media only screen and (max-width: 480px){
                /* /\/\/\/\/\/\/ CLIENT-SPECIFIC MOBILE STYLES /\/\/\/\/\/\/ */
                body, table, td, p, a, li, blockquote{-webkit-text-size-adjust:none !important;} /* Prevent Webkit platforms from changing default text sizes */
                body{width:100% !important; min-width:100% !important;} /* Prevent iOS Mail from adding padding to the body */

                /* /\/\/\/\/\/\/ MOBILE RESET STYLES /\/\/\/\/\/\/ */
                #bodyCell{padding:10px !important;}

                /* /\/\/\/\/\/\/ MOBILE TEMPLATE STYLES /\/\/\/\/\/\/ */

                /* ======== Page Styles ======== */

                /**
                * @tab Mobile Styles
                * @section template width
                * @tip Make the template fluid for portrait or landscape view adaptability. If a fluid layout doesn't work for you, set the width to 300px instead.
                */
                #templateContainer{
                    max-width:600px !important;
                    /*@editable*/ width:100% !important;
                }

                /**
                * @tab Mobile Styles
                * @section heading 1
                * @tip Make the first-level headings larger in size for better readability on small screens.
                */
                h1{
                    /*@editable*/ font-size:24px !important;
                    /*@editable*/ line-height:100% !important;                  
                }

                /**
                * @tab Mobile Styles
                * @section heading 2
                * @tip Make the second-level headings larger in size for better readability on small screens.
                */
                h2{
                    /*@editable*/ font-size:20px !important;
                    /*@editable*/ line-height:100% !important;
                }

                /**
                * @tab Mobile Styles
                * @section heading 3
                * @tip Make the third-level headings larger in size for better readability on small screens.
                */
                h3{
                    /*@editable*/ font-size:18px !important;
                    /*@editable*/ line-height:100% !important;
                }

                /**
                * @tab Mobile Styles
                * @section heading 4
                * @tip Make the fourth-level headings larger in size for better readability on small screens.
                */
                h4{
                    /*@editable*/ font-size:16px !important;
                    /*@editable*/ line-height:100% !important;
                }

                /* ======== Header Styles ======== */

                #templatePreheader{display:none !important;} /* Hide the template preheader to save space */

                /**
                * @tab Mobile Styles
                * @section header image
                * @tip Make the main header image fluid for portrait or landscape view adaptability, and set the image's original width as the max-width. If a fluid setting doesn't work, set the image width to half its original size instead.
                */
                #headerImage{
                    height:auto !important;
                    /*@editable*/ max-width:600px !important;
                    /*@editable*/ width:100% !important;
                }

                /**
                * @tab Mobile Styles
                * @section header text
                * @tip Make the header content text larger in size for better readability on small screens. We recommend a font size of at least 16px.
                */
                .headerContent{
                    /*@editable*/ font-size:20px !important;
                    /*@editable*/ line-height:125% !important;
                }

                /**
                * @tab Mobile Styles
                * @section header text
                * @tip Make the header content text larger in size for better readability on small screens. We recommend a font size of at least 16px.
                */
                .headerContentInfo{
                    /*@editable*/ font-size:20px !important;
                    /*@editable*/ line-height:125% !important;
                    text-align: right;
                }
                /* ======== Body Styles ======== */

                /**
                * @tab Mobile Styles
                * @section body text
                * @tip Make the body content text larger in size for better readability on small screens. We recommend a font size of at least 16px.
                */
                .bodyContent{
                    /*@editable*/ font-size:18px !important;
                    /*@editable*/ line-height:125% !important;
                }

                /* ======== Footer Styles ======== */

                /**
                * @tab Mobile Styles
                * @section footer text
                * @tip Make the body content text larger in size for better readability on small screens.
                */
                .footerContent{
                    /*@editable*/ font-size:14px !important;
                    /*@editable*/ line-height:115% !important;
                }

                .footerContent a{display:block !important;} /* Place footer social and utility links on their own lines, for easier access */
            }
        </style>
    </head>
    <body leftmargin="0" marginwidth="0" topmargin="0" marginheight="0" offset="0">
        <center>
            <table align="center" border="0" cellpadding="0" cellspacing="0" height="100%" width="100%" id="bodyTable">
                <tr>
                    <td align="center" valign="top" id="bodyCell">
                        <!-- BEGIN TEMPLATE // -->
                        <table border="0" cellpadding="0" cellspacing="0" id="templateContainer">
                            <tr>
                                <td align="center" valign="top">
                                    <!-- BEGIN PREHEADER // -->
                                    <table border="0" cellpadding="0" cellspacing="0" width="100%" id="templatePreheader">
                                        <tr>
                                            <td valign="top" class="preheaderContent" style="padding-top:10px; padding-right:20px; padding-bottom:10px; padding-left:20px;">
                                                Rechnung über "{{ Report.InvoicePosition[0].Name | Truncate: 20 }}"{% case Report.InvoicePosition.Size %}{% when 0%}{% when 1 %}{% when 2 %} und einem weiteren Artikel{% else %} und {{ Report.InvoicePosition.Size | Minus: 1 }} weiteren Artikeln{% endcase%} von {{ Report.Company.CompanyName }}
                                            </td>                                            
                                        </tr>
                                    </table>
                                    <!-- // END PREHEADER -->
                                </td>
                            </tr>
                            <tr>
                                <td align="center" valign="top">
                                    <!-- BEGIN HEADER // -->
                                    <table border="0" cellpadding="0" cellspacing="0" width="100%" id="templateHeader">
                                        <tr>
                                            <td valign="top" class="headerContent">
                                                <table border="0" cellpadding="0" cellspacing="0" width="100%">
                                                    <tr>
                                                        <td valign="top" class="headerLogo">
                                                            {% if FirmenLogoUrl != empty -%}
                                                            <img src="{{ FirmenLogoUrl }}" style="max-width:600px;" id="headerImage" alt="Firmenlogo"/>
                                                            {% endif -%}
                                                        </td>
                                                        <td valign="top" class="headerSummary">
                                                            <h1>Rechnung</h1>
                                                            Rechnungsnummer: <em>{{ Report.InvoiceNumber }}</em><br />
                                                            Kundennummer: <em>{{ Report.MandateReference }}</em><br />                                                       
                                                        </td>
                                                    </tr>
                                                </table>                                                
                                            </td>
                                            <td valign="top" class="headerContentInfo">
                                            </td>
                                        </tr>
                                    </table>
                                    <!-- // END HEADER -->
                                </td>
                            </tr>
                            <tr>
                                <td align="center" valign="top">
                                    <!-- BEGIN BODY // -->
                                    <table border="0" cellpadding="0" cellspacing="0" width="100%" id="templateBody">
                                        <tr>
                                            <td valign="top" class="bodyContent">
                                                <!-- BEGIN BODYTEXT // -->
                                                {% if Report.InvoiceBillToAddress.Salutation != empty -%}
                                                    {% case Report.InvoiceBillToAddress.Salutation -%}
                                                        {% when 'Herr' -%}
                                                            Sehr geehrter Herr\
                                                        {% when 'Frau' -%}
                                                            Sehr geehrte Frau\
                                                        {% else -%}
                                                            Sehr geehrte(r) {{ Report.InvoiceBillToAddress.Salutation }}\
                                                    {% endcase -%}
                                                    {% if Report.InvoiceBillToAddress.Title != empty %} {{ Report.InvoiceBillToAddress.Title }}{% endif %} {{ Report.InvoiceBillToAddress.LastName }},
                                                {% else -%} 
                                                    Sehr geehrte Damen und Herren,
                                                {% endif -%}<br />
                                                <br />
                                                vielen Dank für Ihren Auftrag vom {{ Report.CreationDate | Datum: 'D' }}. Ihr Auftrag wurde bearbeitet und wird nun versendet.<br />
                                                Sollten Sie noch Fragen haben, stehen wir Ihnen gerne zur Verfügung.
                                                <!-- // END BODYTEXT -->
                                            </td>
                                        </tr>
                                        <tr>
                                            <td valign="top" class="bodyContent">
                                                <!-- BEGIN SUBHEADER // -->
                                                <h2>Einzelheiten zum Auftrag</h2>
                                                <table border="0" cellpadding="0" cellspacing="0" width="100%" class="bodyData">
                                                    <tr>
                                                        <td valign="top" class="bodyDataLeft" width="100%">
                                                            <h3>Rechnungsadresse:</h3>
                                                            {% if Report.InvoiceBillToAddress.Company != null and Report.InvoiceBillToAddress.Company != empty %}{{ Report.InvoiceBillToAddress.Company }}<br />{% endif %}
                                                            {% if Report.InvoiceBillToAddress.CompanySupplement != null and Report.InvoiceBillToAddress.CompanySupplement != empty != empty %}{{ Report.InvoiceBillToAddress.CompanySupplement }}<br />{% endif %}
                                                            {% if Report.InvoiceBillToAddress.Salutation != null and Report.InvoiceBillToAddress.Salutation != empty %}{{ Report.InvoiceBillToAddress.Salutation }} {% endif %}{% if Report.InvoiceBillToAddress.Title != null and Report.InvoiceBillToAddress.Title != empty %}{{ Report.InvoiceBillToAddress.Title }}{% else %}{{ Report.InvoiceBillToAddress.FirstName }}{% endif %} {%if Report.InvoiceBillToAddress.LastName != null and Report.InvoiceBillToAddress.LastName != empty %}{{ Report.InvoiceBillToAddress.LastName }}{% endif %}<br />
                                                            {% if Report.InvoiceBillToAddress.AddressSupplement != null and Report.InvoiceBillToAddress.AddressSupplement != empty %}{{ Report.InvoiceBillToAddress.AddressSupplement }}<br />{% endif %}
                                                            {{ Report.InvoiceBillToAddress.Address }}<br />
                                                            {{ Report.InvoiceBillToAddress.PostalCode }} {{ Report.InvoiceBillToAddress.City }}<br />
                                                            {% if Report.InvoiceBillToAddress.Country != null and Report.InvoiceBillToAddress.Country != empty %}{{ Report.InvoiceBillToAddress.Country }}<br />{% endif %}
                                                            {% if Report.InvoiceBillToAddress.ValueAddedTaxId > 0 -%}
                                                            <br />
                                                            USt-IdNr.: {{ Report.InvoiceBillToAddress.ValueAddedTaxId }}<br />
                                                            {% endif -%}
                                                        </td>
                                                    </tr>                                               
                                                </table>
                                                <!-- END SUBHEADER // -->                                               
                                            </td>
                                        </tr>
                                        <tr>
                                            <td valign="top" class="bodyContent">
                                                <!-- BEGIN POSITIONS // -->
                                                    <h3>Positionen</h3>
                                                    <hr />
                                                    <table border="0" cellpadding="0" cellspacing="0" width="100%" class="bodyPositions">
                                                    <thead>
                                                        <tr>
                                                            <th></th>
                                                            <th width="100%"></th>
                                                            <th></th>
                                                        </tr>
                                                    </thead>
                                                    <tbody>
                                                        {% assign versandposition = 0 -%}
                                                        {% for position in Report.InvoicePosition -%}
                                                            {% if position.PositionType == 'ShippingPosition' -%}
                                                            {% assign versandart = position.Name -%}
                                                            {% if NettoPreiseBenutzen -%}
                                                            {% assign versandkosten = position.TotalNetPrice -%}
                                                            {% else -%}
                                                            {% assign versandkosten = position.TotalGrossPrice -%}
                                                            {% endif -%}
                                                            {% else -%}
                                                        <tr>       
                                                            <td width="80%" class="PositionDescription">
                                                                {{ position.Quantity | Nummer : 'N2' }}{% if position.Unit != empty %}&nbsp;{{ Position.Unit }}{% else %}x{% endif %}
                                                                {{ position.Name }}<br/>
                                                                {% if IncludeArtikelnummern == true -%}
                                                                <table border="0" cellpadding="0" cellspacing="0" width="100%" class="PositionProperties">
                                                                <tbody>                                                                    
                                                                    <tr class="Artikelnummer">
                                                                        <td class="spacer"><div>&nbsp;</div></td>
                                                                        <td class="name">
                                                                            Artikelnummer:
                                                                        </td><td class="content">
                                                                            {{ position.SKU }}
                                                                        </td>
                                                                    </tr>                                                                    
                                                                </tbody>
                                                                </table>
                                                                {% endif -%} 
                                                                {% if IncludeEinzelpreise == true -%}
                                                                <table border="0" cellpadding="0" cellspacing="0" width="100%" class="PositionProperties">
                                                                <tbody>                                                                    
                                                                    <tr class="Einzelpreis">
                                                                        <td class="spacer"><div>&nbsp;</div></td>
                                                                        <td class="name">
                                                                            Einzelpreis:
                                                                        </td><td class="content">
                                                                            {% if NettoPreiseBenutzen %}{{ position.NetPricePerUnit | Nummer : 'C', Report.CultureInfo | Replace: ' ','&nbsp;' }}{% else %}{{ position.GrossPricePerUnit | Nummer : 'C', Report.CultureInfo | Replace: ' ','&nbsp;' }}{% endif %}
                                                                        </td>
                                                                    </tr>                                                                    
                                                                </tbody>
                                                                </table>
                                                                {% endif -%} 
                                                            </td>
                                                            <td width="20%" class="PositionPrice">
                                                                {% if NettoPreiseBenutzen %}{{ position.TotalNetPrice | Nummer : 'C', Report.CultureInfo | Replace: ' ','&nbsp;' }}{% else %}{{ position.TotalGrossPrice | Nummer : 'C', Report.CultureInfo | Replace: ' ','&nbsp;' }}{% endif %}
                                                            </td>

                                                        </tr>
                                                            {% endif %}
                                                        {% endfor -%}
                                                </tbody>
                                                </table>
                                                <!-- END POSITIONS // -->
                                                <!-- BEGIN SUMMEN // -->
                                                <table border="0" cellpadding="0" cellspacing="0" width="100%" class="Sum">
                                                <tbody>
                                                    <tr>       
                                                        <td valign="top" class="SumPosDescription">
                                                            Verpackung und Versand{% if versandart != null %} ({{ versandart }}){% endif %}:
                                                        </td><td valign="top" class="SumPosPrice" style="border-bottom: 1px solid black">
                                                            {% if versandkosten != empty %}{{ versandkosten | Nummer : 'C', Report.CultureInfo | Replace: ' ','&nbsp;' }}{% else %}{{ 0 | Nummer: 'C', Report.CultureInfo | Replace: ' ','&nbsp;' }}{% endif %}
                                                        </td>
                                                    </tr>                                                    
                                                    {% if Specification.RevealValueAddedTax %}
                                                    {% for invoiceTotals in Report.TotalsInvoice -%}
                                                    {% if invoiceTotals.GrossPriceTotal > 0 -%}
                                                    <tr>
                                                        <td valign="top" class="SumPosDescription">
                                                            Summe Netto ({{invoiceTotals.VATRate | Nummer : 'N' }}%):
                                                        </td><td valign="top" class="SumPosPrice">
                                                            {{ invoiceTotals.NetPriceTotal | Nummer : 'C', Report.CultureInfo | Replace: ' ','&nbsp;' }}
                                                        </td>
                                                    </tr>
                                                    {% endif -%}
                                                    {% endfor -%}                                                   
                                                    {% for invoiceTotals in Report.TotalsInvoice %}
                                                    {% if invoiceTotals.VATRate > 0 -%}
                                                    <tr>
                                                        <td valign="top" class="SumPosDescription">
                                                            zzgl. USt. ({{invoiceTotals.VATRate | Nummer : 'N' }}%):
                                                        </td><td valign="top" class="SumPosPrice">
                                                            {{ invoiceTotals.VATSum | Nummer:'C', Report.CultureInfo | Replace: ' ','&nbsp;' }}
                                                        </td>
                                                    </tr>
                                                    {% endif %}
                                                    {% endfor %}
                                                    {% endif %}
                                                    <tr>
                                                        <td valign="top" class="SumPosDescription">
                                                            <em><b>Gesamtsumme:</b></em>
                                                        </td><td valign="top" class="SumPosPrice" style="border-top: 1px solid black">
                                                            <em><b>{{ Report.TotalGrossPrice | Nummer : 'C', Report.CultureInfo | Replace: ' ','&nbsp;' }}</b></em>
                                                        </td>
                                                    </tr>
                                                </tbody>
                                                </table>
                                                <!-- END SUMMEN // -->                                              
                                            </td>
                                        </tr>
                                        <tr>
                                            <!-- BEGIN ZAHLUNGEN // -->
                                            <td valign="top" class="bodyContent">
                                                <h3>Zahlung</h3>
                                                <table border="0" cellpadding="0" cellspacing="0" width="100%" class="Payments">
                                                <tbody>
                                                    {% assign payments = false -%}
                                                    {% for payment in Report.InvoicePayments -%}
                                                        {% assign payments = true -%}
                                                        <tr>
                                                            <td valign="top" class="PaymentsDescription">
                                                                Zahlung ({{ payment.Name }}) vom {{ payment.PaymentDate | Datum: 'd' }}:
                                                            </td><td valign="top" class="PaymentsPrice">
                                                                {{ payment.Value | Nummer: 'C', Report.CultureInfo | Replace: ' ','&nbsp;' }}
                                                            </td>
                                                        </tr>
                                                    {% endfor -%}
                                                    {% if payments == true -%}
                                                        <tr>
                                                            <td valign="top" class="PaymentsDescription">
                                                                <em>offener Betrag:</em>
                                                            </td><td valign="top" class="PaymentsPrice" style="border-top: 1px solid black">
                                                                <em>{{ Report.OpenGrossPrice | Nummer: 'C', Report.CultureInfo | Replace: ' ','&nbsp;' }}</em>
                                                            </td>
                                                        </tr>                                                       
                                                    {% endif -%}
                                                </tbody>
                                                </table>
                                            </td>       
                                            <!-- END ZAHLUNGEN // -->
                                        </tr>
                                        <tr>
                                            <!-- BEGIN ANMERKUNGEN // -->
                                            <td valign="top" class="bodyContent">
                                                {% if Report.ExemptFromVAT == 'ExemptFromVATnotEU' -%}
                                                    {{ Specification.TextsExemptFromValueAddedTax }}<br />
                                                {% endif -%}
                                                {% if Report.ExemptFromVAT == 'IGL' -%}
                                                  {{ Specification.TextsIGL }}<br />
                                                {% endif -%}
                                                {% if Report.ExemptFromVAT == 'ReverseCharge' -%}
                                                    {{ Specification.TextsReverseCharge }}<br />
                                                {% endif -%}                                             
                                                {% if Report.InvoicePrintingText != empty -%}
                                                    {{ Report.InvoicePrintingText }}<br />
                                                {% endif -%}
                                            </td>       
                                            <!-- END ANMERKUNGEN // -->
                                        </tr>
                                        <tr>
                                            <td valign="top" class="bodyContent">
                                            Mit freundlichen Grüßen<br /><br />
                                            {{ Report.User.Name }}<br />
                                            {{ Report.Company.CompanyName }}
                                            </td>
                                        </tr>
                                    </table>
                                    <!-- // END BODY -->
                                </td>
                            </tr>
                            <tr>
                                <td align="center" valign="top">
                                    <!-- BEGIN FOOTER // -->
                                    <table border="0" cellpadding="0" cellspacing="0" width="100%" id="templateFooter">
                                        <tr>
                                            <td valign="top" class="footerContent">
                                                {% if Report.Company.WebsiteURL != empty %}Besuchen Sie uns auf unserer Homepage unter <a href="{{Report.Company.WebsiteURL}}">{{Report.Company.WebsiteURL}}</a>.<br/>{% endif %}
                                                {% if TwitterProfileUrl != empty -%}
                                                <a href="{{ TwitterProfileUrl }}">Folgen Sie uns auf Twitter</a>&nbsp;&nbsp;&nbsp;
                                                {% endif -%}
                                                {% if FacebookProfileUrl != empty -%}
                                                <a href="{{ FacebookProfileUrl }}">Besuchen Sie uns auf Facebook</a>&nbsp;&nbsp;&nbsp;
                                                {% endif -%}
                                                {% if GoogleProfileUrl != empty -%}
                                                <a href="{{ GoogleProfileUrl }}">Besuchen Sie uns auf Google+</a>&nbsp;&nbsp;&nbsp;
                                                {% endif -%}
                                            </td>
                                        </tr>
                                        <tr>
                                            <td valign="top" class="footerContent" style="padding-top:0;">
                                                <table border="0" cellpadding="0" cellspacing="0" width="100%" id="footerInfo">
                                                <tr>
                                                    <td valign="top" class="footerContent" width="33%">
                                                        <em>Bankverbindung</em><br/>
                                                        {{ Report.Company.AccountHolder }}<br />
                                                        Bank: {{ Report.Company.BankName }}<br />
                                                        BIC: {{ Report.Company.BIC }}<br />
                                                        IBAN: {{ Report.Company.IBAN }}<br />
                                                    </td>
                                                    <td valign="top" class="footerContent" width="33%">
                                                        <em>Anschrift:</em><br />
                                                        {{ Report.Company.CompanyName }}<br />
                                                        {% if Report.Company.ManagingDirector != empty %}{{ Report.Company.ManagingDirector }}<br/>{% endif %}
                                                        {{ Report.Company.Address }}<br />
                                                        {{ Report.Company.PostalCode }} {{ Report.Company.City }}<br />
                                                        {% if Report.Company.Country != empty %}{{ Report.Company.Country }}<br />{% endif %}
                                                        Tel: {{ Report.Company.Phone }}<br />
                                                        {% if Report.Company.Fax != empty %}Fax: {{ Report.Company.Fax }}<br />{% endif %}
                                                    </td>
                                                    <td valign="top" class="footerContent" width="33%">
                                                        <br />
                                                        {% if Report.Company.ValueAddedTaxId != empty %}USt-IdNr.: {{ Report.Company.ValueAddedTaxId }}<br />{% endif %}
                                                        {% if Report.Company.FederalTaxId != empty %}St.Nr.: {{ Report.Company.FederalTaxId }}<br />{% endif %}
                                                        {% if Report.Company.CreditorId != empty %}Gläubiger-IdNr.: {{ Report.Company.CreditorId }}<br />{% endif %} 
                                                    </td>
                                                </tr>
                                                </table>                                                
                                            </td>
                                        </tr>
                                    </table>
                                    <!-- // END FOOTER -->
                                </td>
                            </tr>
                        </table>
                        <!-- // END TEMPLATE -->
                    </td>
                </tr>
            </table>
        </center>
    </body>
</html>

body.plain:
{% comment -%}
JTL-Software Template für E-Mail "Rechnung (Text-Format)", Stand: 20181009
--------------------------------------------------------------------------------------------------------------
Sie können das Template über folgende Variablen steuern:
--------------------------------------------------------------------------------------------------------------
{% endcomment -%}
{% assign IncludeArtikelnummern = false %}{% comment %}Gibt an, ob die Artikelnummern ausgegeben werden{% endcomment -%}
{% assign IncludeEinzelpreise = false %}{% comment %}Gibt an, ob die Einzelpreise ausgegeben werden{% endcomment -%}
{% comment -%}
--------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------
Unterhalb dieses Bereiches sollten nur erfahrene Anwender Änderungen vornehmen. Bei Fragen
steht Ihnen unser Supportforum unter http://forum.jtl-software.de/formulardesigner-editor-open-beta-phase/
zur Verfügung. Gerne helfen Ihnen auch unsere Servicepartner weiter. Einen qualifizierten Service-Partner
finden Sie unter http://www.jtl-software.de/Servicepartner.
--------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------
--------------------------------------------------------------------------------------------------------------
{% endcomment -%}
{% assign NettoPreiseBenutzen = false -%}
{% if Specification.UseNetPrices == true -%}
{% assign NettoPreiseBenutzen = true -%}
{% endif -%}
{{ Report.Company.CompanyName }} Rechnung #{{ Report.InvoiceNumber }}
_____________________________________________________________________________________

{% if Report.InvoiceBillToAddress.Salutation != empty -%}
{% case Report.InvoiceBillToAddress.Salutation -%}
{% when 'Herr' -%}
Sehr geehrter Herr\
{% when 'Frau' -%}
Sehr geehrte Frau\
{% else -%}
Sehr geehrte(r) {{ Report.InvoiceBillToAddress.Salutation }}\
{% endcase -%}
{% if Report.InvoiceBillToAddress.Title != empty %} {{ Report.InvoiceBillToAddress.Title }}{% endif %}{{ Report.InvoiceBillToAddress.LastName }},
{% else -%} 
Sehr geehrte Damen und Herren,
{% endif -%}

vielen Dank für Ihren Auftrag vom {{ Report.CreationDate | Datum: 'D' }}. Ihr Auftrag wurde bearbeitet und wird nun versendet.
Sollten Sie noch Fragen haben, stehen wir Ihnen gerne zur Verfügung.

Einzelheiten zum Auftrag
------------------------

Rechnungsadresse:
{% if Report.InvoiceBillToAddress.Company != null and Report.InvoiceBillToAddress.Company != empty -%}
  {{ Report.InvoiceBillToAddress.Company }}
{% endif -%}
{% if Report.InvoiceBillToAddress.CompanySupplement != null and Report.InvoiceBillToAddress.CompanySupplement != empty -%}
  {{ Report.InvoiceBillToAddress.CompanySupplement }}
{% endif -%}
  {% if Report.InvoiceBillToAddress.Salutation != null and Report.InvoiceBillToAddress.Salutation != empty -%}
{{ Report.InvoiceBillToAddress.Salutation }} \
{% endif -%}
{% if Report.InvoiceBillToAddress.Title != null and Report.InvoiceBillToAddress.Title != empty -%}
{{ Report.InvoiceBillToAddress.Title }} \
{% else -%}
{{ Report.InvoiceBillToAddress.FirstName }} \
{% endif -%}
{% if Report.InvoiceBillToAddress.LastName != null and Report.InvoiceBillToAddress.LastName != empty -%}
{{ Report.InvoiceBillToAddress.LastName }} \
{% endif %}
{% if Report.InvoiceBillToAddress.AddressSupplement != null and Report.InvoiceBillToAddress.AddressSupplement != empty -%}
  {{ Report.InvoiceBillToAddress.AddressSupplement }}
{% endif -%}
  {{ Report.InvoiceBillToAddress.Address }}
  {{ Report.InvoiceBillToAddress.PostalCode }} {{ Report.InvoiceBillToAddress.City }}
{% if Report.InvoiceBillToAddress.Country != null and Report.InvoiceBillToAddress.Country != empty -%}
  {{ Report.InvoiceBillToAddress.Country }}
{% endif -%}
{% if Report.InvoiceBillToAddress.ValueAddedTaxId > 0 -%}

  USt-IdNr.: {{ Report.InvoiceBillToAddress.ValueAddedTaxId }}
{% endif -%}
{% if Report.ServiceDate != null and Report.ServiceDate != empty -%}

  Voraussichtliche Lieferung: {{Report.ServiceDate | Datum: 'd' }}
{% endif -%}
{% if Report.ShippingMethod.PrintingText != null and Report.ShippingMethod.PrintingText != empty -%}
  {{ Report.ShippingMethod.PrintingText }}
{% endif -%}

Positionen:
{% assign versandposition = 0 -%}
{% for position in Report.InvoicePosition -%}
{% if position.PositionType == 'ShippingPosition' -%}
{% assign versandart = position.Name -%}
{% if NettoPreiseBenutzen -%}
{% assign versandkosten = position.TotalNetPrice -%}
{% else -%}
{% assign versandkosten = position.TotalGrossPrice -%}
{% endif -%}
{% else -%}
{% capture menge -%}{{ position.Quantity | Nummer : 'N2' }}{% if position.Unit != empty %} {{ Position.Unit }}{% else %}x{% endif %} {{ position.Name }}{% endcapture -%}
{% capture preis -%}{% if NettoPreiseBenutzen %}{{ position.TotalNetPrice | Nummer : 'C', Report.CultureInfo }}{% else %}{{ position.TotalGrossPrice | Nummer : 'C', Report.CultureInfo }}{% endif %}{% endcapture -%}
  {{ menge | Truncate: 61 | Align: -61 }}{{Tabulator}}{{ preis | Truncate: 15 | Align: 15 }}
{% if IncludeArtikelnummern == true -%}
{% capture artnr %}Artikelnummer: {{ position.SKU }}{% endcapture -%}
    {{ artnr | Truncate: 61 }}
{% endif -%}
{% if IncludeEinzelpreise == true -%}
{% capture ez %}Einzelpreis: {% if NettoPreiseBenutzen %}{{ position.NetPricePerUnit | Nummer : 'C', Report.CultureInfo }}{% else %}{{ position.GrossPricePerUnit | Nummer : 'C', Report.CultureInfo }}{% endif -%}{% endcapture -%}
    {{ ez | Truncate: 59 }}
{% endif -%}
{% endif -%}
{% endfor -%}
{% capture desc %}Verpackung und Versand{% if versandart != null %} ({{ versandart }}){% endif %}:{% endcapture -%}
{% capture price %}{% if versandkosten != empty %}{{ versandkosten | Nummer : 'C', Report.CultureInfo }}{% else %}{{ 0 | Nummer: 'C', Report.CultureInfo }}{% endif %}{%endcapture -%}
  {{ desc | Truncate: 61 | Align: 61 }}{{Tabulator}}{{ price | Truncate: 15 | Align: 15 }}
{% if Specification.RevealValueAddedTax -%}
  {{ ' ' | Align: 61 }}{{Tabulator}}---------------
{% for invoiceTotals in Report.TotalsInvoice -%}
{% if invoiceTotals.GrossPriceTotal > 0 -%}
{% capture desc %}Summe Netto ({{invoiceTotals.VATRate | Nummer : 'N' }}%):{% endcapture -%}
{% capture price %}{{ invoiceTotals.NetPriceTotal | Nummer : 'C', Report.CultureInfo }}{% endcapture -%}
  {{ desc | Truncate: 61 | Align: 61 }}{{Tabulator}}{{ price | Truncate: 15 | Align: 15 }}
{% endif -%}
{% endfor -%}
{% for invoiceTotals in Report.TotalsInvoice -%}
{% if invoiceTotals.GrossPriceTotal > 0 -%}
{% capture desc %}zzgl. USt. ({{invoiceTotals.VATRate | Nummer : 'N' }}%):{% endcapture -%}
{% capture price %}{{ invoiceTotals.VATSum | Nummer:'C', Report.CultureInfo }}{% endcapture -%}
  {{ desc | Truncate: 61 | Align: 61 }}{{Tabulator}}{{ price | Truncate: 15 | Align: 15 }}
{% endif -%}
{% endfor -%}
{% endif -%}
  {{ ' ' | Align: 61 }}{{Tabulator}}===============
  {{ 'Gesamtsumme:' | Truncate: 61 | Align: 61}}{{ Tabulator }}{{ Report.TotalGrossPrice | Nummer : 'C', Report.CultureInfo | Truncate: 15 | Align: 15 }}
  {{ ' ' | Align: 61 }}{{Tabulator}}===============

Zahlung:
{% assign payments = false -%}
{% for payment in Report.InvoicePayments -%}
{% assign payments = true -%}
{% capture desc %}Zahlung ({{ payment.Name }}) vom {{ payment.PaymentDate | Datum: 'd' }}:{% endcapture -%}
{% capture price %}{{ payment.Value | Nummer: 'C', Report.CultureInfo }}{% endcapture -%}
  {{ desc | Truncate: 61 | Align: 61 }}{{Tabulator}}{{ price | Truncate: 15 | Align: 15 }}
{% endfor -%}
{% if payments == true -%}
{% capture desc %}offener Betrag:{% endcapture -%}
{% capture price %}{{ Report.OpenGrossPrice | Nummer: 'C', Report.CultureInfo }}{% endcapture -%}
  {{ ' ' | Align: 61 }}{{Tabulator}}===============
  {{ desc | Truncate: 61 | Align: 61 }}{{Tabulator}}{{ price | Truncate: 15 | Align: 15 }}
{% endif -%}

{% if Report.ExemptFromVAT == 'ExemptFromVATnotEU' -%}
  {{ Specification.TextsExemptFromValueAddedTax }}
{% endif -%}
{% if Report.ExemptFromVAT == 'IGL' -%}
  {{ Specification.TextsIGL }}
{% endif -%}
{% if Report.ExemptFromVAT == 'ReverseCharge' -%}
    {{ Specification.TextsReverseCharge }}
{% endif -%}
{% if Report.InvoicePrintingText != empty -%}
  {{ Report.InvoicePrintingText }}
{% endif -%}

Mit freundlichen Grüßen

